export async function listCustomerOrders(db: Db, customerId: string, since: Date) {
  const orders = await db.query('SELECT * FROM orders WHERE customer_id = $1 AND created_at > $2', [customerId, since]);
  // e81c0d4: attach line items
  for (const order of orders) {
    order.items = await db.query('SELECT * FROM order_items WHERE order_id = $1', [order.id]);
  }
  return orders;
}
